begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table course_objective_fixture(pack uuid,stage uuid,subject uuid,first_source uuid,second_source uuid,other_subject uuid,wrong_source uuid,unscoped uuid,programme uuid,first_academic uuid,second_academic uuid);
grant select,insert,update on course_objective_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','9d100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Two school objectives','Synthetic source hierarchy','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score)values('10000000-0000-4000-8000-000000000001','9d110000-0000-4000-8000-000000000001','9d100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Second objective task','School source',10);
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
insert into course_objective_fixture(pack)select(internal.configure_curriculum('version.create',null,'{"packId":"school-two-objective-golden","kind":"school_custom","framework":"School Custom","programme":"School subject scope","version":"school-1","scope":"Synthetic hierarchy only","sourceStatus":"VERIFIED","rightsStatus":"PERMITTED","sourceLocation":"repo:synthetic","sourceChecksum":null,"synthetic":true,"reason":"Technical source case"}','two-objective-pack',repeat('a',64),'two-objective')->>'id')::uuid;
update course_objective_fixture set stage=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',null,'type','stage','title','School stage','description','School-authored stage','code',null,'sequence',1,'subjectId',null,'yearGroupId','42000000-0000-4000-8000-000000000001'),'two-objective-stage',repeat('b',64),'two-objective')->>'id')::uuid;
update course_objective_fixture set subject=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',stage,'type','subject','title','School mathematics','description','School subject hierarchy','code',null,'sequence',1,'subjectId','43000000-0000-4000-8000-000000000001','yearGroupId',null),'two-objective-subject',repeat('c',64),'two-objective')->>'id')::uuid;
update course_objective_fixture set first_source=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',subject,'type','objective','title','Explain the school example','description','School explanation','code',null,'sequence',1,'subjectId',null,'yearGroupId',null),'two-objective-first',repeat('d',64),'two-objective')->>'id')::uuid;
update course_objective_fixture set second_source=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',subject,'type','objective','title','Check the school example','description','School checking','code',null,'sequence',2,'subjectId',null,'yearGroupId',null),'two-objective-second',repeat('e',64),'two-objective')->>'id')::uuid;
update course_objective_fixture set other_subject=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',stage,'type','subject','title','Other school subject','description','Different subject hierarchy','code',null,'sequence',2,'subjectId',null,'yearGroupId',null),'two-objective-other-subject',repeat('f',64),'two-objective')->>'id')::uuid;
update course_objective_fixture set wrong_source=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',other_subject,'type','objective','title','Wrong hierarchy objective','description','Different source subject','code',null,'sequence',1,'subjectId',null,'yearGroupId',null),'two-objective-wrong',repeat('f',64),'two-objective')->>'id')::uuid;
update course_objective_fixture set unscoped=(internal.configure_curriculum('reference.create',null,jsonb_build_object('packVersionId',pack,'parentId',null,'type','objective','title','Unscoped school objective','description','No subject hierarchy','code',null,'sequence',1,'subjectId',null,'yearGroupId',null),'two-objective-unscoped',repeat('f',64),'two-objective')->>'id')::uuid;
select internal.transition_curriculum_lifecycle((select pack from course_objective_fixture),'{"state":"APPROVED","expectedRevision":1,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Reviewed synthetic school source","confirmTransition":true}',null,'objective-lifecycle-0',repeat('a',64),'curriculum-fixture');
select internal.transition_curriculum_lifecycle((select pack from course_objective_fixture),'{"state":"ACTIVE","expectedRevision":2,"reviewBasis":"SCHOOL_AUTHORED","artifactDirectory":null,"replacementVersionId":null,"reason":"Reviewed synthetic school source","confirmTransition":true}',null,'objective-lifecycle-1',repeat('a',64),'curriculum-fixture');
update course_objective_fixture set programme=(internal.configure_curriculum('programme.create',null,jsonb_build_object('packVersionId',pack,'name','School subject programme','classId','30000000-0000-4000-8000-000000000001','subjectId','43000000-0000-4000-8000-000000000001','yearGroupId','42000000-0000-4000-8000-000000000001','confirmConfiguration',true),'two-objective-programme',repeat('a',64),'two-objective')->>'id')::uuid;
update course_objective_fixture set first_academic=(internal.configure_curriculum('course.configure','9d100000-0000-4000-8000-000000000001',jsonb_build_object('programmeId',programme,'referenceId',first_source,'expectedVersion',1,'confirmConfiguration',true),'two-objective-course',repeat('b',64),'two-objective')->>'academicReferenceId')::uuid;
select is(jsonb_array_length(internal.read_course_academic_references('9d100000-0000-4000-8000-000000000001',25,null)->'items'),1,'Only the initial course objective is approved');
select is(internal.read_course_objective_page('9d100000-0000-4000-8000-000000000001',25,null)->>'scopeStatus','READY','Inherited same-pack subject/year hierarchy is explicit');
select throws_ok($$select internal.approve_course_objective('9d100000-0000-4000-8000-000000000001',jsonb_build_object('referenceId',(select wrong_source from course_objective_fixture),'expectedVersion',1,'reason','Cannot change subject by null fields','confirmConfiguration',true),'two-objective-wrong-approval',repeat('c',64),'two-objective')$$,'22023',null,'Different subject ancestor is rejected even with null direct subject');
select throws_ok($$select internal.approve_course_objective('9d100000-0000-4000-8000-000000000001',jsonb_build_object('referenceId',(select unscoped from course_objective_fixture),'expectedVersion',1,'reason','Cannot infer missing hierarchy','confirmConfiguration',true),'two-objective-unscoped-approval',repeat('c',64),'two-objective')$$,'22023',null,'Missing hierarchy is not a wildcard');
select throws_ok($$select internal.approve_course_objective('9d100000-0000-4000-8000-000000000001',jsonb_build_object('referenceId',(select second_source from course_objective_fixture),'expectedVersion',1,'reason','Reason without human confirmation','confirmConfiguration',false),'two-objective-unconfirmed',repeat('c',64),'two-objective')$$,'22023',null,'Explicit human objective approval is required');
update course_objective_fixture set second_academic=(internal.approve_course_objective('9d100000-0000-4000-8000-000000000001',jsonb_build_object('referenceId',second_source,'expectedVersion',1,'reason','Reviewed exact school subject and year','confirmConfiguration',true),'two-objective-approve',repeat('d',64),'two-objective')->>'academicReferenceId')::uuid;
select lives_ok($$select internal.approve_course_objective('9d100000-0000-4000-8000-000000000001',jsonb_build_object('referenceId',(select second_source from course_objective_fixture),'expectedVersion',1,'reason','Reviewed exact school subject and year','confirmConfiguration',true),'two-objective-approve',repeat('d',64),'two-objective')$$,'Original-key replay preserves one approval');
select is(jsonb_array_length(internal.read_course_academic_references('9d100000-0000-4000-8000-000000000001',25,null)->'items'),2,'Both approved objectives are course choices');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select lives_ok($$select internal.link_assessment_reference('9d110000-0000-4000-8000-000000000001',(select second_academic from course_objective_fixture),1)$$,'Teacher can link the separately approved objective to an assessment');
select throws_ok($$select internal.link_assessment_reference('9d110000-0000-4000-8000-000000000001','61000000-0000-4000-8000-000000000001',2)$$,'22023',null,'Other approved school reference cannot bypass pinned course approval');
select throws_ok($$select internal.approve_course_objective('9d100000-0000-4000-8000-000000000001','{}','two-objective-teacher-denied',repeat('e',64),'two-objective')$$,'42501',null,'Teacher cannot grant curriculum authority');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.read_course_academic_references('9d100000-0000-4000-8000-000000000001',25,null)$$,'42501',null,'Learner cannot enumerate staff curriculum choices');
reset role;
select is((select count(*)from app.course_objective_approvals where course_id='9d100000-0000-4000-8000-000000000001'),2::bigint,'Approval replay leaves exactly two immutable mappings');
select is((select academic_reference_id from app.programme_course_contexts where course_id='9d100000-0000-4000-8000-000000000001'),(select first_academic from course_objective_fixture),'Pinned original programme source is preserved');
select throws_ok($$update app.course_objective_approvals set reason='Overwrite'where course_id='9d100000-0000-4000-8000-000000000001'$$,'55000',null,'Course objective approval cannot be overwritten');
select throws_ok($$truncate app.course_objective_approvals$$,'55000',null,'Course objective approval cannot be truncated');
select ok(not has_table_privilege('cuevo_api','app.course_objective_approvals','SELECT')and not has_table_privilege('authenticated','app.course_objective_approvals','INSERT'),'Approval records have no raw API/browser grants');
select ok(not has_function_privilege('cuevo_worker','internal.approve_course_objective(uuid,jsonb,text,text,text)','EXECUTE')and not has_function_privilege('authenticated','internal.read_course_objective_page(uuid,integer,uuid)','EXECUTE'),'Worker/browser cannot use protected curriculum commands');
select*from finish();rollback;
